    if (!пр.работает) return;
    стоят.push([...наОси(у, конец - о.площадкаДлина / 2, -уПлощадки), у]);
    стоят.push([...наОси(у, площадкаОт - кб.длина / 2 - о.стоянкаЗазор, уНастила), у]);
