    дороги: дороги, кроны: кроны, пальмы: пальмы, стоят: стоят, идут: идут,
    рифы: пятна(о.рифов, о.рифПятен, о.рифРазмах, о.рифПятно, о.рифЗаБерегом, ш.рифы),
    облака: пятна(о.облаков, о.облакоПятен, о.облакоРазмах, о.облакоПятно, о.облакоЗаБерегом, ш.облака)
